('mathl1e_001', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 7x − 5 = 30, what is the value of x?', '["25/7", "35", "6", "5"]'::jsonb, 3, null, 'Add 5: 7x = 35. Divide by 7: x = 5.', 'published', 'import', now()),
('mathl1e_002', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If x/5 − 2 = 6, what is the value of x?', null, null, '["40"]'::jsonb, 'Add 2: x/5 = 8. Multiply by 5: x = 40.', 'published', 'import', now()),
('mathl1e_003', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 6(x − 3) = 42, what is the value of x?', '["13", "10", "4", "7"]'::jsonb, 1, null, 'Divide by 6: x − 3 = 7, so x = 10.', 'published', 'import', now()),
('mathl1e_004', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 3x + 8 = 5x − 10, what is the value of x?', null, null, '["9"]'::jsonb, 'Subtract 3x and add 10: 18 = 2x, so x = 9.', 'published', 'import', now()),
('mathl1e_005', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'A gym charges a $25 sign-up fee plus $15 per month. Kai has paid $130 in total. How many months has he been a member?', '["5", "9", "8", "7"]'::jsonb, 3, null, '25 + 15m = 130, so 15m = 105 and m = 7.', 'published', 'import', now()),
('mathl1e_006', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function g is defined by g(x) = 4x − 7. What is g(5)?', '["20", "13", "−2", "27"]'::jsonb, 1, null, 'g(5) = 4(5) − 7 = 13.', 'published', 'import', now()),
('mathl1e_007', 'math', 1, 'Algebra', 'Linear functions', null, null, 'What is the slope of the line through (2, 3) and (6, 11)?', null, null, '["2"]'::jsonb, 'Slope = (11 − 3) ÷ (6 − 2) = 8 ÷ 4 = 2.', 'published', 'import', now()),
('mathl1e_008', 'math', 1, 'Algebra', 'Linear functions', null, null, 'Which equation represents a line with slope −3 and y-intercept 5?', '["y = −3x + 5", "y = 5x − 3", "y = −3x − 5", "y = 3x + 5"]'::jsonb, 0, null, 'In y = mx + b, m is the slope and b is the y-intercept.', 'published', 'import', now()),
('mathl1e_009', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A candle is 30 centimeters tall and burns down 1.5 centimeters each hour. How tall is it after 8 hours, in centimeters?', '["28.5", "18", "12", "22.5"]'::jsonb, 1, null, 'It burns 1.5 × 8 = 12 cm, leaving 30 − 12 = 18 cm.', 'published', 'import', now()),
('mathl1e_010', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'x + y = 15
y = 2x

What is the value of x?', '["3", "5", "10", "7.5"]'::jsonb, 1, null, 'Substitute: x + 2x = 15, so 3x = 15 and x = 5.', 'published', 'import', now()),
('mathl1e_011', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, '2x + y = 11
x − y = 1

What is the value of y?', null, null, '["3"]'::jsonb, 'Adding the equations gives 3x = 12, so x = 4. Then y = 4 − 1 = 3.', 'published', 'import', now()),
('mathl1e_012', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'Adult tickets cost $8 and child tickets cost $5. A family buys 6 tickets for $39. How many adult tickets do they buy?', '["5", "4", "2", "3"]'::jsonb, 3, null, 'a + c = 6 and 8a + 5c = 39. Substituting c = 6 − a: 8a + 30 − 5a = 39, so 3a = 9 and a = 3.', 'published', 'import', now()),
('mathl1e_013', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which value of x is a solution to 2x − 3 ≤ 7?', '["8", "6", "5", "7"]'::jsonb, 2, null, '2x ≤ 10, so x ≤ 5. Only 5 works.', 'published', 'import', now()),
('mathl1e_014', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'A ride requires riders to be at least 48 inches tall. Which inequality describes the height h, in inches, of a rider who is allowed on the ride?', '["h > 48", "h < 48", "h ≥ 48", "h ≤ 48"]'::jsonb, 2, null, '"At least 48" means 48 or more.', 'published', 'import', now()),
('mathl1e_015', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 4(2x − 1) + 3x?', '["11x − 1", "11x − 4", "8x − 1", "5x − 4"]'::jsonb, 1, null, '4(2x − 1) = 8x − 4. Adding 3x gives 11x − 4.', 'published', 'import', now()),
('mathl1e_016', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (3x^{2})(2x^{5})?', '["5x^{10}", "6x^{10}", "5x^{7}", "6x^{7}"]'::jsonb, 3, null, 'Multiply the numbers (3 × 2 = 6) and add the exponents (2 + 5 = 7).', 'published', 'import', now()),
('mathl1e_017', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x − 4)(x + 4)?', '["x^{2} − 16", "x^{2} − 8x − 16", "x^{2} + 16", "x^{2} − 8"]'::jsonb, 0, null, 'x^{2} + 4x − 4x − 16 = x^{2} − 16.', 'published', 'import', now()),
('mathl1e_018', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is a factored form of x^{2} + 7x + 12?', '["(x − 3)(x − 4)", "(x + 1)(x + 12)", "(x + 2)(x + 6)", "(x + 3)(x + 4)"]'::jsonb, 3, null, '3 and 4 multiply to 12 and add to 7.', 'published', 'import', now()),
('mathl1e_019', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If x^{2} = 121 and x < 0, what is the value of x?', '["−11", "−121", "11", "60.5"]'::jsonb, 0, null, 'x could be 11 or −11. Since x < 0, x = −11.', 'published', 'import', now()),
('mathl1e_020', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to (x − 3)(x + 8) = 0?', '["x = 3 only", "x = −3 and x = 8", "x = 3 and x = −8", "x = −3 and x = −8"]'::jsonb, 2, null, 'Set each factor equal to 0: x − 3 = 0 gives 3, and x + 8 = 0 gives −8.', 'published', 'import', now()),
('mathl1e_021', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If x^{2}/2 = 18 and x > 0, what is the value of x?', null, null, '["6"]'::jsonb, 'Multiply by 2: x^{2} = 36, so x = 6.', 'published', 'import', now()),
('mathl1e_022', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = x^{2} − 3x. What is f(4)?', '["10", "28", "−4", "4"]'::jsonb, 3, null, 'f(4) = 16 − 12 = 4.', 'published', 'import', now()),
('mathl1e_023', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'A town''s rabbit population is 200 and doubles every year. What will the population be in 3 years?', '["800", "600", "1,600", "1,200"]'::jsonb, 2, null, '200 × 2 × 2 × 2 = 1,600.', 'published', 'import', now()),
('mathl1e_024', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'Which point is on the graph of y = 2^{x}?', '["(3, 8)", "(2, 2)", "(3, 6)", "(0, 0)"]'::jsonb, 0, null, '2^{3} = 8, so (3, 8) is on the graph.', 'published', 'import', now()),
('mathl1e_025', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'What is the vertex of the graph of y = (x − 5)^{2}?', '["(5, 0)", "(0, 5)", "(−5, 0)", "(0, −5)"]'::jsonb, 0, null, 'y is smallest (0) when x − 5 = 0, so the vertex is (5, 0).', 'published', 'import', now()),
('mathl1e_026', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A car uses 3 gallons of gas to travel 96 miles. At this rate, how many gallons does it need to travel 160 miles?', '["5", "3.2", "4", "6"]'::jsonb, 0, null, 'The car goes 96 ÷ 3 = 32 miles per gallon. 160 ÷ 32 = 5 gallons.', 'published', 'import', now()),
('mathl1e_027', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'The ratio of cats to dogs at an animal shelter is 3 to 4. There are 42 cats and dogs in all. How many are dogs?', null, null, '["24"]'::jsonb, 'The animals split into 3 + 4 = 7 equal parts of 6. Dogs: 4 × 6 = 24.', 'published', 'import', now()),
('mathl1e_028', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'How many inches are in 3.5 feet?', '["42", "38", "35", "40"]'::jsonb, 0, null, 'There are 12 inches in a foot: 3.5 × 12 = 42.', 'published', 'import', now()),
('mathl1e_029', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Lena types 45 words per minute. How many minutes will it take her to type 900 words?', '["20", "15", "30", "45"]'::jsonb, 0, null, '900 ÷ 45 = 20.', 'published', 'import', now()),
('mathl1e_030', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'What is 15% of 240?', '["36", "48", "16", "24"]'::jsonb, 0, null, '0.15 × 240 = 36.', 'published', 'import', now()),
('mathl1e_031', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A meal costs $25. Ana leaves a 20% tip. What is the total she pays, in dollars?', null, null, '["30"]'::jsonb, 'The tip is 0.20 × 25 = 5, so the total is 25 + 5 = 30.', 'published', 'import', now()),
('mathl1e_032', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'The price of a book rose from $40 to $50. What was the percent increase?', '["50%", "25%", "20%", "10%"]'::jsonb, 1, null, 'The increase is 10, and 10 ÷ 40 = 0.25 = 25%.', 'published', 'import', now()),
('mathl1e_033', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the mean of 6, 8, 11, 15, and 20?', '["60", "15", "12", "11"]'::jsonb, 2, null, 'The sum is 60, and 60 ÷ 5 = 12.', 'published', 'import', now()),
('mathl1e_034', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the median of 3, 9, 4, 12, 7, 10?', null, null, '["8"]'::jsonb, 'In order: 3, 4, 7, 9, 10, 12. The middle two values are 7 and 9, and their average is 8.', 'published', 'import', now()),
('mathl1e_035', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the mode of 2, 5, 5, 7, 8, 8, 8, 9?', '["5", "7", "8", "6.5"]'::jsonb, 2, null, '8 appears three times, more than any other value.', 'published', 'import', now()),
('mathl1e_036', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["Hours", "Earnings ($)"], "r": [["2", "30"], ["5", "75"], ["8", "120"]]}'::jsonb, 'The table shows how much Ty earns for different numbers of hours worked. At this rate, how much will he earn for 10 hours, in dollars?', '["165", "135", "150", "120"]'::jsonb, 2, null, 'He earns 30 ÷ 2 = 15 dollars per hour, so 10 hours pays 150.', 'published', 'import', now()),
('mathl1e_037', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'As the outside temperature rises, the number of cups of lemonade a stand sells tends to rise too. What kind of association is this?', '["No association", "Constant", "Positive", "Negative"]'::jsonb, 2, null, 'Both quantities increase together.', 'published', 'import', now()),
('mathl1e_038', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A spinner has 8 equal sections numbered 1 through 8. What is the probability of spinning a number greater than 5?', '["1/2", "5/8", "1/8", "3/8"]'::jsonb, 3, null, '6, 7, and 8 are greater than 5: 3 out of 8.', 'published', 'import', now()),
('mathl1e_039', 'math', 1, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'In a random sample of 50 shoppers at a store, 35 brought a reusable bag. About how many of the store''s 2,000 shoppers that day would you expect to have brought a reusable bag?', '["350", "1,750", "700", "1,400"]'::jsonb, 3, null, '35/50 = 70%, and 70% of 2,000 is 1,400.', 'published', 'import', now()),
('mathl1e_040', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A triangle has a base of 12 centimeters and a height of 7 centimeters. What is its area, in square centimeters?', '["19", "84", "42", "38"]'::jsonb, 2, null, 'Area = (1/2)(12)(7) = 42.', 'published', 'import', now()),
('mathl1e_041', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangle is 14 meters long and 9 meters wide. What is its perimeter, in meters?', null, null, '["46"]'::jsonb, 'Perimeter = 2(14 + 9) = 46.', 'published', 'import', now()),
('mathl1e_042', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cube has edges 7 centimeters long. What is its volume, in cubic centimeters?', '["49", "21", "294", "343"]'::jsonb, 3, null, '7 × 7 × 7 = 343.', 'published', 'import', now()),
('mathl1e_043', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles are supplementary. One measures 112°. What is the measure of the other?', '["68°", "78°", "248°", "22°"]'::jsonb, 0, null, 'Supplementary angles add to 180°: 180 − 112 = 68.', 'published', 'import', now()),
('mathl1e_044', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two lines cross, forming four angles. One of the angles measures 47°. What is the measure of the angle vertical (directly opposite) to it?', '["94°", "47°", "43°", "133°"]'::jsonb, 1, null, 'Vertical angles are equal.', 'published', 'import', now()),
('mathl1e_045', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'An isosceles triangle has two base angles that each measure 50°. What is the measure of the third angle, in degrees?', null, null, '["80"]'::jsonb, '180 − 50 − 50 = 80.', 'published', 'import', now()),
('mathl1e_046', 'math', 1, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?', '["108", "15", "13", "21"]'::jsonb, 1, null, '9^{2} + 12^{2} = 81 + 144 = 225, and √225 = 15.', 'published', 'import', now()),
('mathl1e_047', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a diameter of 14 inches. What is its circumference, in inches?', '["28π", "14π", "49π", "7π"]'::jsonb, 1, null, 'Circumference = π × diameter = 14π.', 'published', 'import', now()),
('mathl1e_048', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has an area of 36π square units. What is its radius?', null, null, '["6"]'::jsonb, 'πr^{2} = 36π, so r^{2} = 36 and r = 6.', 'published', 'import', now()),
('mathl2e_001', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 3(2x − 5) = 4x + 7, what is the value of x?', null, null, '["11"]'::jsonb, '6x − 15 = 4x + 7, so 2x = 22 and x = 11.', 'published', 'import', now()),
('mathl2e_002', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 7x + 4 = 3x + 24, what is the value of 2x?', '["10", "5", "14", "20"]'::jsonb, 0, null, '4x = 20, so x = 5 and 2x = 10.', 'published', 'import', now()),
('mathl2e_003', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If x/4 + x/2 = 9, what is the value of x?', '["12", "9", "36", "6"]'::jsonb, 0, null, 'x/4 + 2x/4 = 3x/4 = 9, so x = 12.', 'published', 'import', now()),
('mathl2e_004', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'A car rental costs $45 per day plus a one-time $30 fee. Lucia paid $255 in total. For how many days did she rent the car?', null, null, '["5"]'::jsonb, '30 + 45d = 255, so 45d = 225 and d = 5.', 'published', 'import', now()),
('mathl2e_005', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A line passes through (−2, 1) and (3, 11). Which equation represents the line?', '["y = 2x − 3", "y = (1/2)x + 2", "y = 5x + 2", "y = 2x + 5"]'::jsonb, 3, null, 'Slope = (11 − 1) ÷ (3 + 2) = 2. Then 1 = 2(−2) + b gives b = 5.', 'published', 'import', now()),
('mathl2e_006', 'math', 2, 'Algebra', 'Linear functions', null, null, 'The function f is defined by f(x) = mx + 4, where m is a constant. If f(3) = 19, what is m?', null, null, '["5"]'::jsonb, '3m + 4 = 19, so 3m = 15 and m = 5.', 'published', 'import', now()),
('mathl2e_007', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A shop uses C = 12n + 150 to find the cost C, in dollars, of printing n T-shirts. What does 12 represent?', '["The number of T-shirts printed", "The total cost of the order", "The cost of each additional T-shirt", "The one-time setup fee"]'::jsonb, 2, null, '12 is the slope: each extra shirt adds $12. The 150 is the setup fee.', 'published', 'import', now()),
('mathl2e_008', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which line is parallel to y = −2x + 7 and passes through (1, 3)?', '["y = −2x + 3", "y = (1/2)x + 2.5", "y = 2x + 1", "y = −2x + 5"]'::jsonb, 3, null, 'Parallel lines share slope −2. Then 3 = −2(1) + b, so b = 5.', 'published', 'import', now()),
('mathl2e_009', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'y = 3x − 4
2x + y = 11

If (x, y) is the solution to the system, what is the value of x + y?', null, null, '["8"]'::jsonb, 'Substitute: 2x + 3x − 4 = 11, so x = 3 and y = 5. Then x + y = 8.', 'published', 'import', now()),
('mathl2e_010', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, '4x + 3y = 25
2x − 3y = −1

What is the value of y?', '["3", "4", "1", "7"]'::jsonb, 0, null, 'Adding the equations: 6x = 24, so x = 4. Then 16 + 3y = 25, so y = 3.', 'published', 'import', now()),
('mathl2e_011', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'A store sells notebooks for $3 each and binders for $7 each. Ari bought 12 items for $56. How many binders did Ari buy?', '["7", "8", "4", "5"]'::jsonb, 3, null, 'n + b = 12 and 3n + 7b = 56. Substituting n = 12 − b: 36 + 4b = 56, so b = 5.', 'published', 'import', now()),
('mathl2e_012', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'Which system of equations has no solution?', '["y = x and y = 2x", "y = 3x + 2 and y = 3x − 1", "y = 3x + 2 and y = −3x + 2", "y = 3x + 2 and 2y = 6x + 4"]'::jsonb, 1, null, 'Lines with the same slope and different y-intercepts are parallel and never meet. The equations 3x + 2 and 2y = 6x + 4 describe the same line.', 'published', 'import', now()),
('mathl2e_013', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'Which describes all solutions to −4x + 6 > 18?', '["x > −3", "x < −3", "x < 3", "x > 3"]'::jsonb, 1, null, '−4x > 12. Dividing by −4 reverses the sign: x < −3.', 'published', 'import', now()),
('mathl2e_014', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'A taxi charges $3.50 plus $2.25 per mile. Max has $30. What is the greatest whole number of miles he can ride?', null, null, '["11"]'::jsonb, '3.50 + 2.25m ≤ 30 gives 2.25m ≤ 26.50, so m ≤ 11.77... The greatest whole number is 11.', 'published', 'import', now()),
('mathl2e_015', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (3x − 1)^{2}?', '["9x^{2} − 6x + 1", "9x^{2} − 6x − 1", "9x^{2} + 1", "3x^{2} − 6x + 1"]'::jsonb, 0, null, '(3x − 1)(3x − 1) = 9x^{2} − 3x − 3x + 1 = 9x^{2} − 6x + 1.', 'published', 'import', now()),
('mathl2e_016', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is a factored form of 3x^{2} + 10x + 8?', '["(3x + 8)(x + 1)", "(3x + 4)(x + 2)", "(3x + 2)(x + 4)", "(x + 2)(x + 4)"]'::jsonb, 1, null, '(3x + 4)(x + 2) = 3x^{2} + 6x + 4x + 8 = 3x^{2} + 10x + 8.', 'published', 'import', now()),
('mathl2e_017', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to x^{5}/x^{−2}, for x ≠ 0?', '["x^{−3}", "x^{3}", "x^{7}", "x^{−10}"]'::jsonb, 2, null, 'Subtract exponents: 5 − (−2) = 7.', 'published', 'import', now()),
('mathl2e_018', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to √50?', '["10√5", "2√5", "25√2", "5√2"]'::jsonb, 3, null, '√50 = √(25 × 2) = 5√2.', 'published', 'import', now()),
('mathl2e_019', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the positive solution of x^{2} − 2x − 24 = 0?', null, null, '["6"]'::jsonb, '(x − 6)(x + 4) = 0, so x = 6 or x = −4.', 'published', 'import', now()),
('mathl2e_020', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to (x + 2)^{2} = 49?', '["x = 9 and x = −5", "x = 5 only", "x = 7 and x = −7", "x = 5 and x = −9"]'::jsonb, 3, null, 'x + 2 = 7 or x + 2 = −7, so x = 5 or x = −9.', 'published', 'import', now()),
('mathl2e_021', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If 2^{x + 1} = 32, what is the value of x?', '["16", "5", "3", "4"]'::jsonb, 3, null, '32 = 2^{5}, so x + 1 = 5 and x = 4.', 'published', 'import', now()),
('mathl2e_022', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If √(2x − 1) = 7, what is the value of x?', null, null, '["25"]'::jsonb, 'Square both sides: 2x − 1 = 49, so 2x = 50 and x = 25.', 'published', 'import', now()),
('mathl2e_023', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If x/5 = 20/x and x > 0, what is the value of x?', '["10", "100", "4", "20"]'::jsonb, 0, null, 'Cross-multiply: x^{2} = 100, so x = 10.', 'published', 'import', now()),
('mathl2e_024', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = 3(x − 1)^{2} + 4. What is the minimum value of f?', '["3", "1", "4", "−1"]'::jsonb, 2, null, '(x − 1)^{2} is never negative and equals 0 at x = 1, so the minimum is 4.', 'published', 'import', now()),
('mathl2e_025', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'A car worth $20,000 loses 10% of its value each year. What is it worth after 2 years, in dollars?', '["18,000", "16,200", "14,580", "16,000"]'::jsonb, 1, null, '20,000 × 0.9 × 0.9 = 16,200.', 'published', 'import', now()),
('mathl2e_026', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'If g(x) = x^{2} + 1 and h(x) = x − 3, what is g(h(5))?', null, null, '["5"]'::jsonb, 'h(5) = 2, and g(2) = 4 + 1 = 5.', 'published', 'import', now()),
('mathl2e_027', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'At which x-values does the graph of y = x^{2} − 8x + 12 cross the x-axis?', '["x = 3 and x = 4", "x = 2 and x = 6", "x = −2 and x = −6", "x = 12 only"]'::jsonb, 1, null, 'x^{2} − 8x + 12 = (x − 2)(x − 6), which is 0 at x = 2 and x = 6.', 'published', 'import', now()),
('mathl2e_028', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A recipe for 6 servings uses 2.5 cups of rice. How many cups of rice are needed for 15 servings?', null, null, '["6.25", "25/4"]'::jsonb, '2.5 ÷ 6 × 15 = 6.25 cups.', 'published', 'import', now()),
('mathl2e_029', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A runner''s pace is 8 minutes per mile. What is her speed, in miles per hour?', '["480", "7.5", "6.5", "8"]'::jsonb, 1, null, '60 minutes ÷ 8 minutes per mile = 7.5 miles per hour.', 'published', 'import', now()),
('mathl2e_030', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Gas costs $3.60 per gallon, and a car gets 30 miles per gallon. How much will the gas cost to drive 450 miles, in dollars?', '["54", "45", "162", "48"]'::jsonb, 0, null, '450 ÷ 30 = 15 gallons, and 15 × 3.60 = 54.', 'published', 'import', now()),
('mathl2e_031', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, '36 is 45% of what number?', null, null, '["80"]'::jsonb, '0.45n = 36, so n = 80.', 'published', 'import', now()),
('mathl2e_032', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A $120 coat is on sale for 35% off. A sales tax of 8% is then added to the sale price. What is the total cost, in dollars?', '["87.60", "92.40", "78.00", "84.24"]'::jsonb, 3, null, 'Sale price: 0.65 × 120 = 78. With tax: 78 × 1.08 = 84.24.', 'published', 'import', now()),
('mathl2e_033', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A school''s enrollment fell from 1,250 students to 1,100 students. What was the percent decrease?', '["15%", "13.6%", "12%", "88%"]'::jsonb, 2, null, 'The drop is 150, and 150 ÷ 1,250 = 0.12 = 12%.', 'published', 'import', now()),
('mathl2e_034', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean of Rosa''s first 5 test scores is 84. What score does she need on the 6th test to raise her mean to 86?', null, null, '["96"]'::jsonb, 'She needs a total of 6 × 86 = 516. Her first five total 5 × 84 = 420, so she needs 96.', 'published', 'import', now()),
('mathl2e_035', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The data set 12, 15, 15, 18, 20, 52 has an outlier of 52. By how much does the mean decrease when 52 is removed?', '["5.5", "6", "16", "36"]'::jsonb, 1, null, 'With 52, the mean is 132 ÷ 6 = 22. Without it, the mean is 80 ÷ 5 = 16. The decrease is 6.', 'published', 'import', now()),
('mathl2e_036', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["x", "y"], "r": [["1", "3"], ["2", "6"], ["3", "12"], ["4", "24"]]}'::jsonb, 'Which equation best models the data in the table?', '["y = 3x", "y = 1.5(2)^{x}", "y = 3x + 3", "y = 2x + 1.5"]'::jsonb, 1, null, 'Each y-value is double the one before, so the model is exponential with factor 2. At x = 1, 1.5(2) = 3.', 'published', 'import', now()),
('mathl2e_037', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'The line of best fit y = 2.4x + 15 predicts a plant''s height y, in centimeters, x weeks after planting. What is the predicted height after 10 weeks?', '["39", "17.4", "24", "41.4"]'::jsonb, 0, null, '2.4(10) + 15 = 39.', 'published', 'import', now()),
('mathl2e_038', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Walk", "Bus", "Car"], "r": [["Grade 9", "20", "35", "15"], ["Grade 10", "25", "30", "25"]]}'::jsonb, 'The table shows how 150 students get to school.

If a student who rides the bus is chosen at random, what is the probability that the student is in grade 10?', '["6/13", "1/5", "7/13", "3/8"]'::jsonb, 0, null, '35 + 30 = 65 students ride the bus, and 30 are in grade 10: 30/65 = 6/13.', 'published', 'import', now()),
('mathl2e_039', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A bag has 5 red and 3 green marbles. A marble is drawn, put back, and a second marble is drawn. What is the probability that both are green?', '["3/32", "3/28", "9/64", "3/8"]'::jsonb, 2, null, 'With replacement, each draw has probability 3/8: (3/8)(3/8) = 9/64.', 'published', 'import', now()),
('mathl2e_040', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'Which method is most likely to produce a sample that represents all registered voters in a town?', '["Surveying people at a single gym", "Surveying the mayor''s campaign volunteers", "Randomly selecting names from the town''s full list of registered voters", "Asking listeners to call in to a radio show"]'::jsonb, 2, null, 'A random selection from the whole population avoids favoring any one group.', 'published', 'import', now()),
('mathl2e_041', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A forester measured 60 randomly selected trees in a large forest and found a mean height of 18 meters. Which conclusion is most reasonable?', '["The forest has exactly 60 trees", "No tree in the forest is taller than 18 meters", "The mean height of all trees in the forest is probably close to 18 meters", "Every tree in the forest is 18 meters tall"]'::jsonb, 2, null, 'A random sample''s mean is a reasonable estimate of the population mean, not a description of every tree.', 'published', 'import', now()),
('mathl2e_042', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A trapezoid has bases of 10 and 16 and a height of 7. What is its area?', null, null, '["91"]'::jsonb, 'Area = (1/2)(10 + 16)(7) = 91.', 'published', 'import', now()),
('mathl2e_043', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cylinder has a radius of 4 and a height of 9. What is its volume?', '["36π", "72π", "288π", "144π"]'::jsonb, 3, null, 'V = πr^{2}h = π(16)(9) = 144π.', 'published', 'import', now()),
('mathl2e_044', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two parallel lines are cut by a transversal. Two alternate interior angles measure (3x + 10)° and (5x − 30)°. What is the value of x?', '["20", "40", "25", "10"]'::jsonb, 0, null, 'Alternate interior angles are equal: 3x + 10 = 5x − 30, so 40 = 2x and x = 20.', 'published', 'import', now()),
('mathl2e_045', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'What is the sum of the interior angles of a hexagon?', '["1,080°", "540°", "360°", "720°"]'::jsonb, 3, null, '(n − 2) × 180 = 4 × 180 = 720.', 'published', 'import', now()),
('mathl2e_046', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Rectangle A is 4 inches by 6 inches. Rectangle B is similar to rectangle A, and its longer side is 15 inches. What is the length of its shorter side, in inches?', null, null, '["10"]'::jsonb, 'The scale factor is 15 ÷ 6 = 2.5, so the shorter side is 4 × 2.5 = 10.', 'published', 'import', now()),
('mathl2e_047', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In a right triangle, one angle measures 30° and the hypotenuse is 18. What is the length of the side opposite the 30° angle?', '["6", "18√3", "9", "9√3"]'::jsonb, 2, null, 'In a 30°-60°-90° triangle, the side opposite 30° is half the hypotenuse.', 'published', 'import', now()),
('mathl2e_048', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'If sin x° = cos 40° and 0 < x < 90, what is the value of x?', null, null, '["50"]'::jsonb, 'sin x° = cos(90 − x)°, so 90 − x = 40 and x = 50.', 'published', 'import', now()),
('mathl2e_049', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has equation (x − 4)^{2} + (y + 1)^{2} = 36. What are its center and radius?', '["Center (4, −1), radius 36", "Center (−4, 1), radius 36", "Center (4, −1), radius 6", "Center (−4, 1), radius 6"]'::jsonb, 2, null, '(x − h)^{2} + (y − k)^{2} = r^{2} has center (h, k) and radius r. Here h = 4, k = −1, and r = 6.', 'published', 'import', now()),
('mathl2e_050', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a radius of 10. What is the length of an arc intercepted by a central angle of 72°?', '["2π", "4π", "10π", "20π"]'::jsonb, 1, null, 'The arc is 72/360 = 1/5 of the circumference 20π, which is 4π.', 'published', 'import', now()),
('mathl3e_001', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If (2/3)(x − 6) = (1/4)(x + 9), what is the value of x?', null, null, '["15"]'::jsonb, 'Multiply by 12: 8(x − 6) = 3(x + 9), so 8x − 48 = 3x + 27, 5x = 75 and x = 15.', 'published', 'import', now()),
('mathl3e_002', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation 4(x − c) = 2(2x + 3), c is a constant. For what value of c does the equation have infinitely many solutions?', '["6", "−6", "−3/2", "3/2"]'::jsonb, 2, null, 'Expanding: 4x − 4c = 4x + 6. The equation holds for every x when −4c = 6, so c = −3/2.', 'published', 'import', now()),
('mathl3e_003', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If 3x − 2y = 8, what is the value of 6y − 9x?', '["−8", "16", "−24", "24"]'::jsonb, 2, null, '6y − 9x = −3(3x − 2y) = −3(8) = −24.', 'published', 'import', now()),
('mathl3e_004', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A linear function f satisfies f(1) = 7 and f(5) = 19. The function g is defined by g(x) = f(2x). What is g(3)?', null, null, '["22"]'::jsonb, 'The slope of f is 12 ÷ 4 = 3, so f(x) = 3x + 4. Then g(3) = f(6) = 22.', 'published', 'import', now()),
('mathl3e_005', 'math', 3, 'Algebra', 'Linear functions', null, null, 'In the xy-plane, the lines 3x + ky = 12 and 6x − 4y = 5 are perpendicular. What is the value of k?', null, null, '["4.5", "9/2"]'::jsonb, 'The second line has slope 6/4 = 3/2. The first has slope −3/k. Perpendicular slopes multiply to −1: (−3/k)(3/2) = −1, so k = 9/2.', 'published', 'import', now()),
('mathl3e_006', 'math', 3, 'Algebra', 'Linear functions', null, null, 'Gym A charges C = 40m + 75 dollars for m months. Gym B charges C = 55m + 15 dollars for m months. For how many months do the two gyms cost the same?', '["5", "4", "3", "6"]'::jsonb, 1, null, '40m + 75 = 55m + 15 gives 60 = 15m, so m = 4.', 'published', 'import', now()),
('mathl3e_007', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '2x + 3y = 17
3x + 2y = 18

What is the value of x + y?', null, null, '["7"]'::jsonb, 'Adding the equations: 5x + 5y = 35, so x + y = 7.', 'published', 'import', now()),
('mathl3e_008', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'ax + 2y = 6
3x + by = 9

In the system, a and b are constants. If the system has infinitely many solutions, what is the value of a + b?', '["4", "5", "9", "6"]'::jsonb, 1, null, 'Multiplying the second equation by 2/3 gives 2x + (2b/3)y = 6. For the equations to match, a = 2 and 2b/3 = 2, so b = 3. Then a + b = 5.', 'published', 'import', now()),
('mathl3e_009', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'A jar holds 40 coins, all dimes and quarters, worth $6.25 in total. How many quarters are in the jar?', '["25", "15", "20", "10"]'::jsonb, 1, null, 'd + q = 40 and 10d + 25q = 625 (in cents). Substituting d = 40 − q: 400 + 15q = 625, so q = 15.', 'published', 'import', now()),
('mathl3e_010', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'Which point (x, y) is a solution to the system y > 2x − 1 and y ≤ −x + 5?', '["(0, 3)", "(2, 3)", "(3, 4)", "(−1, 7)"]'::jsonb, 0, null, '(0, 3): 3 > −1 and 3 ≤ 5. For (2, 3), 3 is not greater than 3. For (3, 4) and (−1, 7), y is greater than −x + 5.', 'published', 'import', now()),
('mathl3e_011', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'To earn an A, a student needs a mean score of at least 85 on five tests. Her first four scores are 78, 92, 81, and 86. What is the least score she can earn on the fifth test and still get an A?', null, null, '["88"]'::jsonb, 'She needs a total of at least 5 × 85 = 425. Her first four total 337, so she needs 425 − 337 = 88.', 'published', 'import', now()),
('mathl3e_012', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'If −3 ≤ a ≤ 2 and 1 ≤ b ≤ 4, what is the greatest possible value of a − b?', '["5", "6", "−2", "1"]'::jsonb, 3, null, 'a − b is greatest when a is as large as possible and b is as small as possible: 2 − 1 = 1.', 'published', 'import', now()),
('mathl3e_013', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{2} − 9)/(x^{2} + x − 6), for x ≠ −3 and x ≠ 2?', '["−3/2", "(x − 3)/(x + 2)", "(x + 3)/(x − 2)", "(x − 3)/(x − 2)"]'::jsonb, 3, null, 'Factor: (x − 3)(x + 3) over (x + 3)(x − 2). Cancel x + 3 to get (x − 3)/(x − 2).', 'published', 'import', now()),
('mathl3e_014', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If (2x + k)^{2} = 4x^{2} − 20x + 25 for all x, what is the value of k?', null, null, '["-5", "−5"]'::jsonb, '(2x + k)^{2} = 4x^{2} + 4kx + k^{2}. Matching 4k = −20 gives k = −5, and k^{2} = 25 checks.', 'published', 'import', now()),
('mathl3e_015', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If x^{2/3} = 9 and x > 0, what is the value of x?', '["81", "3", "27", "6"]'::jsonb, 2, null, 'Raise both sides to the 3/2 power: x = 9^{3/2} = (√9)^{3} = 27.', 'published', 'import', now()),
('mathl3e_016', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'For x ≠ 0, which expression is equivalent to (x + 1/x)^{2} − (x − 1/x)^{2}?', '["4", "0", "2x^{2}", "4/x^{2}"]'::jsonb, 0, null, '(x^{2} + 2 + 1/x^{2}) − (x^{2} − 2 + 1/x^{2}) = 4.', 'published', 'import', now()),
('mathl3e_017', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'For which value of k does the equation x^{2} − kx + 16 = 0 have no real solutions?', '["5", "8", "−9", "10"]'::jsonb, 0, null, 'There are no real solutions when the discriminant k^{2} − 64 is negative, so −8 < k < 8. Only 5 is in that range.', 'published', 'import', now()),
('mathl3e_018', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If x + 1/x = 5, what is the value of x^{2} + 1/x^{2}?', null, null, '["23"]'::jsonb, 'Square both sides: x^{2} + 2 + 1/x^{2} = 25, so x^{2} + 1/x^{2} = 23.', 'published', 'import', now()),
('mathl3e_019', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'y = x^{2} − 3
y = 2x

The graphs of the equations intersect at two points. What is the sum of the y-coordinates of these points?', '["6", "4", "2", "8"]'::jsonb, 1, null, 'x^{2} − 3 = 2x gives (x − 3)(x + 1) = 0, so x = 3 or −1. The points are (3, 6) and (−1, −2), and 6 + (−2) = 4.', 'published', 'import', now()),
('mathl3e_020', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the sum of the solutions to |2x − 5| = 9?', null, null, '["5"]'::jsonb, '2x − 5 = 9 gives x = 7, and 2x − 5 = −9 gives x = −2. The sum is 5.', 'published', 'import', now()),
('mathl3e_021', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If (x + 3)/(x − 1) = (x + 7)/(x + 1), and x ≠ 1 and x ≠ −1, what is the value of x?', '["1", "3", "−5", "5"]'::jsonb, 3, null, 'Cross-multiply: (x + 3)(x + 1) = (x + 7)(x − 1), so x^{2} + 4x + 3 = x^{2} + 6x − 7. Then 10 = 2x and x = 5.', 'published', 'import', now()),
('mathl3e_022', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A ball''s height, in feet, t seconds after it is thrown is h(t) = −16t^{2} + 64t + 5. What is the ball''s maximum height, in feet?', '["133", "64", "5", "69"]'::jsonb, 3, null, 'The vertex is at t = −64/(2 × −16) = 2. h(2) = −64 + 128 + 5 = 69.', 'published', 'import', now()),
('mathl3e_023', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = 2^{x}, and g(x) = f(x + 3). Which expression is equivalent to g(x)?', '["2^{x} + 3", "6 · 2^{x}", "8 · 2^{x}", "3 · 2^{x}"]'::jsonb, 2, null, 'g(x) = 2^{x + 3} = 2^{3} · 2^{x} = 8 · 2^{x}.', 'published', 'import', now()),
('mathl3e_024', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The value of an investment, in dollars, t years after it is made is V(t) = 2,000(1.03)^{4t}. By what percent does the value grow each quarter (one-fourth of a year)?', '["3%", "12%", "4%", "1.03%"]'::jsonb, 0, null, 'Each quarter adds 1 to the exponent 4t, multiplying the value by 1.03, which is 3% growth.', 'published', 'import', now()),
('mathl3e_025', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = (x − 1)(x − 5)(x + 2). What is the y-intercept of the graph of f?', '["(0, −10)", "(0, 10)", "(0, 2)", "(0, 5)"]'::jsonb, 1, null, 'f(0) = (−1)(−5)(2) = 10.', 'published', 'import', now()),
('mathl3e_026', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = a(x − 3)^{2} − 4 passes through the point (5, 4). What is the value of a?', null, null, '["2"]'::jsonb, '4 = a(2)^{2} − 4, so 4a = 8 and a = 2.', 'published', 'import', now()),
('mathl3e_027', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A container holds 40 liters of a 30% salt solution. How many liters of pure salt must be added to make a 40% salt solution?', null, null, '["20/3", "6.666", "6.667"]'::jsonb, 'Salt: 12 + s. Total: 40 + s. Then 12 + s = 0.4(40 + s), so 0.6s = 4 and s = 20/3.', 'published', 'import', now()),
('mathl3e_028', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Machine A makes 120 parts per hour and machine B makes 80 parts per hour. Working together, how many minutes will they take to make 500 parts?', '["150", "250", "120", "200"]'::jsonb, 0, null, 'Together they make 200 parts per hour, so 500 parts take 2.5 hours, or 150 minutes.', 'published', 'import', now()),
('mathl3e_029', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A pool holds 18,000 gallons. A hose fills it at 1.5 gallons per second. How many hours will it take to fill the empty pool?', '["10/3", "5", "3", "12"]'::jsonb, 0, null, '18,000 ÷ 1.5 = 12,000 seconds, and 12,000 ÷ 3,600 = 10/3 hours (3 hours 20 minutes).', 'published', 'import', now()),
('mathl3e_030', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A price is increased by 20%, and then the new price is increased by 25%. The two increases are equivalent to a single increase of what percent?', '["5%", "45%", "50%", "22.5%"]'::jsonb, 2, null, '1.20 × 1.25 = 1.50, a 50% increase.', 'published', 'import', now()),
('mathl3e_031', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'After a 12% increase, a town''s population is 5,600. What was the population before the increase?', null, null, '["5000", "5,000"]'::jsonb, '1.12P = 5,600, so P = 5,000.', 'published', 'import', now()),
('mathl3e_032', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Data set A has 10 values with a mean of 30. Data set B has 15 values with a mean of 40. What is the mean of the 25 values combined?', '["35", "37.5", "34", "36"]'::jsonb, 3, null, 'Totals: 300 + 600 = 900. 900 ÷ 25 = 36.', 'published', 'import', now()),
('mathl3e_033', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A data set of 9 values has a median of 20. Each value is doubled, and then 5 is added to each result. What is the median of the new data set?', null, null, '["45"]'::jsonb, 'Doubling and adding 5 keeps the values in the same order, so the new median is 2(20) + 5 = 45.', 'published', 'import', now()),
('mathl3e_034', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'The equation y = 250(0.92)^{x} models the number of trout in a lake x years after 2020. Which statement best describes the meaning of 0.92 in the model?', '["The trout population decreases by 0.92 trout each year", "The trout population increases by 92% each year", "The trout population decreases by 8% each year", "The trout population decreases by 92% each year"]'::jsonb, 2, null, 'A factor of 0.92 keeps 92% each year, which is an 8% decrease.', 'published', 'import', now()),
('mathl3e_035', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Likes", "Dislikes"], "r": [["Tried a free sample", "84", "36"], ["Did not try a sample", "45", "35"]]}'::jsonb, 'The table shows the results of a survey of 200 shoppers about a new snack.

If a shopper who likes the snack is chosen at random, what is the probability that the shopper tried a free sample?', '["28/43", "21/50", "7/10", "129/200"]'::jsonb, 0, null, '84 + 45 = 129 shoppers like the snack, and 84 of them tried a sample: 84/129 = 28/43.', 'published', 'import', now()),
('mathl3e_036', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'Events A and B are independent, with P(A) = 0.4 and P(B) = 0.5. What is the probability that A or B (or both) occurs?', '["0.9", "0.2", "0.45", "0.7"]'::jsonb, 3, null, 'Add the two probabilities and subtract the chance both occur: 0.4 + 0.5 − (0.4)(0.5) = 0.7.', 'published', 'import', now()),
('mathl3e_037', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'Researchers randomly assigned 200 volunteers from one city to drink either green tea or water daily for a year. The green tea group ended with lower average cholesterol. Which conclusion is best supported?', '["Drinking water raises cholesterol", "Green tea is linked to lower cholesterol, but no cause can be inferred", "Green tea lowers cholesterol for every person in the country", "Green tea likely caused lower cholesterol for people similar to the volunteers"]'::jsonb, 3, null, 'Random assignment supports a cause-and-effect conclusion, but only for people like those studied, since the volunteers weren''t a random sample of everyone.', 'published', 'import', now()),
('mathl3e_038', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A survey of 100 randomly chosen residents has a margin of error of 6 percentage points. Which change would most likely reduce the margin of error?', '["Surveying only residents who agree with the question", "Surveying a larger random sample of residents", "Asking the same 100 residents again", "Surveying a smaller random sample"]'::jsonb, 1, null, 'Larger random samples produce smaller margins of error.', 'published', 'import', now()),
('mathl3e_039', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A square is inscribed in a circle of radius 5, so each corner of the square touches the circle. What is the area of the square?', '["100", "50", "25", "25π"]'::jsonb, 1, null, 'The square''s diagonal is a diameter, 10. A square with diagonal d has area d^{2}/2 = 50.', 'published', 'import', now()),
('mathl3e_040', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cone has a volume of 96π and a radius of 6. What is its height?', null, null, '["8"]'::jsonb, '(1/3)π(36)h = 12πh = 96π, so h = 8.', 'published', 'import', now()),
('mathl3e_041', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'Each edge of a cube is increased by 50%. By what factor does the volume increase?', '["2.25", "1.5", "4.5", "3.375"]'::jsonb, 3, null, 'The volume is multiplied by 1.5^{3} = 3.375.', 'published', 'import', now()),
('mathl3e_042', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'The angles of a triangle are in the ratio 2 : 3 : 7. What is the measure, in degrees, of the largest angle?', null, null, '["105"]'::jsonb, '2 + 3 + 7 = 12 parts, each 180 ÷ 12 = 15°. The largest is 7 × 15 = 105.', 'published', 'import', now()),
('mathl3e_043', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'A triangle has sides 7, 24, and 25. A similar triangle has a shortest side of 21. What is the perimeter of the larger triangle?', '["156", "72", "168", "112"]'::jsonb, 2, null, 'The scale factor is 21 ÷ 7 = 3. The original perimeter is 56, so the new one is 168.', 'published', 'import', now()),
('mathl3e_044', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle ABC with right angle C, tan A = 0.75 and the hypotenuse AB = 20. What is the length of BC, the side opposite angle A?', '["16", "12", "15", "9"]'::jsonb, 1, null, 'tan A = 3/4 means the legs are in the ratio 3 : 4 with hypotenuse 5. Scaling by 4 gives legs 12 and 16, and BC = 12.', 'published', 'import', now()),
('mathl3e_045', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'An isosceles right triangle has a hypotenuse of 8. What is the length of each leg?', '["4√2", "2√2", "8√2", "4"]'::jsonb, 0, null, 'In a 45°-45°-90° triangle, the hypotenuse is leg × √2, so each leg is 8/√2 = 4√2.', 'published', 'import', now()),
('mathl3e_046', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A line is tangent to a circle of radius 9 at point T. Point P is on the line, 15 units from the circle''s center. What is the length of PT?', null, null, '["12"]'::jsonb, 'A tangent is perpendicular to the radius at T, so PT = √(15^{2} − 9^{2}) = √144 = 12.', 'published', 'import', now()),
('mathl3e_047', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'An inscribed angle in a circle intercepts an arc of 140°. What is the measure of the inscribed angle?', '["140°", "35°", "70°", "280°"]'::jsonb, 2, null, 'An inscribed angle is half its intercepted arc.', 'published', 'import', now()),
('mathl3e_048', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has equation x^{2} + y^{2} + 10x − 4y + 20 = 0. What is the radius of the circle?', null, null, '["3"]'::jsonb, 'Complete the squares: (x + 5)^{2} + (y − 2)^{2} = −20 + 25 + 4 = 9, so the radius is 3.', 'published', 'import', now())
on conflict (id) do nothing;
